import { test, expect } from '@playwright/test';

test.describe('Login Loading Spinner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display loading spinner while login request is processing', async ({ page }) => {
    // Intercept the login API request
    await page.route('**/api/auth/login', (route) => {
      route.abort('blockedbyclient');
    });

    // Get email input by label and fill with valid email
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    // Get password input by label and fill with valid password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Password123');

    // Get login button by role and click it
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Wait for the loading spinner to appear
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Verify loading spinner has correct class
    await expect(loadingSpinner).toHaveClass(/loading-spinner/);

    // Verify login button is disabled during loading
    await expect(loginButton).toBeDisabled();

    // Wait for the loading spinner to disappear
    await page.waitForTimeout(1000);
    await expect(loadingSpinner).not.toBeVisible();

    // Verify login button is enabled after loading
    await expect(loginButton).not.toBeDisabled();
  });

  test('should hide loading spinner when login request fails', async ({ page }) => {
    // Intercept the login API request and respond with an error
    await page.route('**/api/auth/login', (route) => {
      route.fulfill({
        status: 401,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Invalid credentials' }),
      });
    });

    // Get email input by label and fill with valid email
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    // Get password input by label and fill with invalid password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword');

    // Get login button by role and click it
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Wait for loading spinner to appear
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for the error response
    await page.waitForTimeout(1500);

    // Verify loading spinner is hidden after error
    await expect(loadingSpinner).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid credentials/i);
    await expect(errorMessage).toBeVisible();

    // Verify login button is enabled after error
    await expect(loginButton).not.toBeDisabled();
  });
});
